//! GIN Library public registry metadata; publisher texts are independent terminals.
use super::{common,static_list::blocks_for,Adapter,PlanRow};
use crate::guidelines::{doc::{GuidelineDoc,Relation,Rights},fetch::Fetcher,html::{blocks_from_html,sel,text_of},registry::SourceEntry};
use anyhow::{bail,Context,Result};
use scraper::Html;
use serde_json::json;
use std::collections::HashSet;
use url::Url;
pub struct GinLibrary;
const ROOT:&str="https://guidelines.ebmportal.com/";
fn catalog(raw:&str,base:&Url)->Result<(Vec<String>,Option<String>)>{let d=Html::parse_document(raw);let root=d.select(&sel("main#main-content")).next().context("GIN catalog root missing")?;let mut links=vec![];for a in root.select(&sel("article.node--type-collection-item h2 a[href]")){if let Some(u)=a.value().attr("href").and_then(|x|common::link(base,x)){if Url::parse(&u)?.origin()==base.origin(){links.push(u)}}}if links.is_empty(){bail!("GIN catalog records missing")};let next=d.select(&sel("a[rel='next'][href]")).next().and_then(|a|a.value().attr("href")).and_then(|h|common::link(base,h)).filter(|u|Url::parse(u).map(|x|x.origin()==base.origin()&&x.path()=="/").unwrap_or(false));Ok((links,next))}
fn record(raw:&str,base:&Url)->Result<(String,String,Vec<serde_json::Value>)>{let d=Html::parse_document(raw);let title=d.select(&sel("main#main-content h1")).next().map(|x|text_of(&x)).context("GIN record title missing")?;let root=d.select(&sel("main#main-content article.node--view-mode-full .container-content")).next().context("GIN full registry record missing")?;if root.select(&sel(".field__label")).next().is_none(){bail!("GIN registry fields missing")};let mut links=vec![];for a in d.select(&sel("main#main-content article.node--view-mode-full .header-content a[href]")){let label=text_of(&a);if label.to_lowercase().contains("view publication"){if let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)){links.push(json!({"url":url,"label":label,"role":"publisher_terminal_unverified","rights":"unknown"}))}}}Ok((title,root.html(),links))}
fn native_fields(raw:&str,base:&Url)->Result<Vec<serde_json::Value>>{let d=Html::parse_document(raw);let root=d.select(&sel("main#main-content article.node--view-mode-full .container-content")).next().context("GIN registry fields missing")?;let mut fields=vec![];for field in root.select(&sel(".field")){let Some(label)=field.select(&sel(".field__label")).next().map(|x|text_of(&x))else{continue};for value in field.select(&sel(".field__item")){let text=text_of(&value);if text.is_empty(){continue}let links=value.select(&sel("a[href]")).filter_map(|a|a.value().attr("href").and_then(|h|common::link(base,h)).map(|url|json!({"url":url,"label":text_of(&a)}))).collect::<Vec<_>>();fields.push(json!({"label":label,"value":text,"links":links,"source_url":base.as_str(),"scope":"gin_registry_record"}));}}Ok(fields)}
fn issue(s:&SourceEntry,u:String,e:String)->PlanRow{PlanRow{source_id:s.id.clone(),doc_key:format!("gin-{}-unresolved",common::short_hash(&u)),url:u,title:None,rendition:None,version:None,extra:json!({"discovery_error":e})}}
/// Listing entries' Drupal node ids (from the RIS/CSV selection inputs) and titles, keyed by the listed record URL.
/// Some listed path aliases return 404 (e.g. "allergie-presumee-aux-penicillines-..."), while the same record is
/// served at the site's canonical system path `/node/<nid>` (whose `<link rel=canonical>` names that alias).
fn catalog_nids(raw:&str,base:&Url)->std::collections::HashMap<String,(String,String)>{
    let d=Html::parse_document(raw);
    let mut out=std::collections::HashMap::new();
    for art in d.select(&sel("main#main-content article.node--type-collection-item")){
        let Some(a)=art.select(&sel("h2 a[href]")).next() else{continue};
        let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)) else{continue};
        let nid=art.select(&sel("input[nid]")).filter_map(|i|i.value().attr("nid")).find(|n|!n.is_empty()&&n.chars().all(|c|c.is_ascii_digit()));
        if let Some(nid)=nid{out.insert(url,(nid.to_string(),text_of(&a)));}
    }
    out
}
fn norm(s:&str)->String{s.split_whitespace().collect::<Vec<_>>().join(" ")}
/// The `/node/<nid>` URL and listed title for a listed record URL, when the listing gave a node id.
fn node_fallback(u:&str,nids:&std::collections::HashMap<String,(String,String)>)->Option<(String,String)>{
    let (nid,listed)=nids.get(u)?;
    Some((Url::parse(ROOT).ok()?.join(&format!("node/{nid}")).ok()?.to_string(),listed.clone()))
}
/// Accept a node page as the listed record only if it parses as a full record with the listed title.
fn accept_node(u:&str,node:&str,listed:&str,html:&str,base:&Url)->Result<String>{
    let (title,_,_)=record(html,base)?;
    if norm(&title)!=norm(listed){bail!("GIN listed alias {u} is HTTP 404 and {node} title {title:?} differs from the listed title {listed:?}")}
    Ok(format!("Listed record alias {u} returned HTTP 404; the record was fetched from the site's canonical node path {node} (node id from the listing), whose title matches the listing."))
}
/// Fetch a listed record; on HTTP 404 of its alias, use `/node/<nid>` from the listing when that page's title equals
/// the listed title. Returns the response, the URL it was fetched from and a note when the fallback was used.
async fn fetch_record(f:&Fetcher,u:&str,nids:&std::collections::HashMap<String,(String,String)>)->Result<(crate::guidelines::fetch::Fetched,String,Option<String>)>{
    match f.get_ok(u).await{
        Ok(p)=>Ok((p,u.to_string(),None)),
        Err(e) if format!("{e:#}").contains("HTTP 404")=>{
            let Some((node,listed))=node_fallback(u,nids) else{return Err(e)};
            let p=f.get_ok(&node).await.map_err(|e2|e.context(format!("node fallback {node}: {e2:#}")))?;
            let note=accept_node(u,&node,&listed,&p.text(),&Url::parse(&p.record.final_url)?)?;
            Ok((p,node,Some(note)))
        }
        Err(e)=>Err(e),
    }
}
#[async_trait::async_trait]impl Adapter for GinLibrary{
 async fn discover(&self,s:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let mut next=Some(s.catalog_url.as_deref().unwrap_or(ROOT).to_string());let mut seen=HashSet::new();let mut rows=vec![];while let Some(url)=next.take(){if !seen.insert(url.clone()){rows.push(issue(s,url,"GIN pagination cycle".into()));break}if seen.len()>500{rows.push(issue(s,url,"GIN pagination bound reached".into()));break}let p=match f.get_ok(&url).await{Ok(x)=>x,Err(e)=>{rows.push(issue(s,url,format!("GIN page unavailable: {e:#}")));break}};let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(ROOT)?.origin(){bail!("GIN redirect outside source")};let (urls,n)=catalog(&p.text(),&b)?;let nids=catalog_nids(&p.text(),&b);next=n;for u in urls{let(p,fetched_url,alias_note)=match fetch_record(f,&u,&nids).await{Ok(x)=>x,Err(e)=>{rows.push(issue(s,u,format!("GIN record unavailable: {e:#}")));if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}continue}};let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(ROOT)?.origin(){rows.push(issue(s,u,"GIN record redirect outside source".into()));continue}match record(&p.text(),&b){Ok((title,body,links))=>{let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&links))?.as_bytes());rows.push(PlanRow{source_id:s.id.clone(),doc_key:format!("gin-{}-{}",common::short_hash(&u),&hash[..12]),url:fetched_url.clone(),title:Some(title.clone()),rendition:Some("html".into()),version:None,extra:json!({"snapshot":hash,"listing_url":u,"listing_alias_note":alias_note})});if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}for link in &links{let Some(target)=link["url"].as_str()else{continue};if !Url::parse(target).map(|x|x.path().to_lowercase().ends_with(".pdf")).unwrap_or(false){continue}match f.get_ok(target).await{Ok(asset) if asset.is_pdf()&&Url::parse(&asset.record.final_url)?.host_str()==Url::parse(target)?.host_str()=>{let sha=asset.record.sha256;rows.push(PlanRow{source_id:s.id.clone(),doc_key:format!("gin-publisher-{}-{}",common::short_hash(target),&sha[..12]),url:target.into(),title:Some(title.clone()),rendition:Some("pdf".into()),version:None,extra:json!({"role":"publisher_document","pdf_sha256":sha,"registry_url":u,"source_label":link["label"]})})},Ok(_)=>rows.push(issue(s,target.into(),"GIN publisher terminal is not an independently validated same-host PDF".into())),Err(e)=>rows.push(issue(s,target.into(),format!("GIN publisher PDF unavailable: {e:#}")))}if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}},Err(e)=>rows.push(issue(s,u,format!("GIN record template: {e:#}")))}if limit.is_some_and(|n|rows.len()>=n){return Ok(rows)}}}Ok(rows)}
 async fn extract(&self,s:&SourceEntry,f:&Fetcher,r:&PlanRow)->Result<GuidelineDoc>{if let Some(e)=r.extra["discovery_error"].as_str(){bail!("{e}")};if r.rendition.as_deref()==Some("pdf"){let p=f.get_ok(&r.url).await?;if !p.is_pdf()||Url::parse(&p.record.final_url)?.host_str()!=Url::parse(&r.url)?.host_str()||r.extra["pdf_sha256"].as_str()!=Some(p.record.sha256.as_str()){bail!("GIN publisher PDF changed or redirected; re-plan")};let(blocks,mut warnings,_)=blocks_for(&p,None,30).await?;if blocks.is_empty(){bail!("GIN publisher PDF has no converted text")};warnings.push("Publisher PDF conversion retains text but physical pages, visual tables, figures and recommendation completeness are not verified. This asset has rights independent from the registry record.".into());let parent=r.extra["registry_url"].as_str().context("GIN publisher PDF parent missing")?;return Ok(GuidelineDoc{source_id:s.id.clone(),doc_key:r.doc_key.clone(),work_key:Some(format!("gin-publisher-{}",common::short_hash(&r.url))),url:r.url.clone(),title:r.title.clone().unwrap_or_else(||r.url.clone()),item_type:Some("publisher_document".into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("Publisher PDF rights are independent of registry metadata and not established.".into()),..Default::default()},relations:vec![Relation{rel:"related".into(),target:parent.into(),scope:Some("GIN source-labelled View Publication link".into()),evidence_url:Some(parent.into())}],blocks,fetches:vec![p.record],warnings,..Default::default()})}let p=f.get_ok(&r.url).await?;let b=Url::parse(&p.record.final_url)?;if b.origin()!=Url::parse(ROOT)?.origin(){bail!("GIN record redirect outside source")};let(title,body,links)=record(&p.text(),&b)?;let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&links))?.as_bytes());if r.extra["snapshot"].as_str()!=Some(hash.as_str()){bail!("GIN record changed; re-plan")};let fields=native_fields(&p.text(),&b)?;let(blocks,mut warnings)=blocks_from_html(&body,Some(&b),None);warnings.push("Registry metadata only; expected publication and evidence-search dates are not publication dates. Publisher terminal, access and rights remain independent and unverified. Pagination has not been reconciled as a complete inventory.".into());if let Some(n)=r.extra["listing_alias_note"].as_str(){warnings.push(n.into())}Ok(GuidelineDoc{source_id:s.id.clone(),doc_key:r.doc_key.clone(),work_key:Some(format!("gin-{}",common::short_hash(r.extra["listing_url"].as_str().unwrap_or(&r.url)))),url:r.url.clone(),title,item_type:Some("registry_record".into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),..Default::default()},blocks,attachments:links,search_metadata:json!({"native_fields":fields,"record_html":body}),fetches:vec![p.record],warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const CAT:&str=concat!(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/gin_library/research-1.part-1.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/gin_library/research-1.part-2.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/gin_library/research-1.part-3.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/gin_library/research-1.part-4.html")));const DETAIL:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/gin_library/research-2.html"));
#[test]fn real_registry_date_roles(){let(d,n)=catalog(CAT,&Url::parse(ROOT).unwrap()).unwrap();assert_eq!(d.len(),10);assert!(n.unwrap().contains("page=1"));let(t,b,_)=record(DETAIL,&Url::parse(ROOT).unwrap()).unwrap();assert!(t.contains("Orthotic Management"));assert!(b.contains("Expected Publication Date")&&b.contains("1 March 2026")&&b.contains("Date of Last Evidence Search")&&b.contains("1 November 2023")&&b.contains("Development"));}
#[tokio::test]async fn real_registry_metadata_is_not_clinical_body(){let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();let u="https://guidelines.ebmportal.com/orthotic-management-adolescent-idiopathic-scoliosis";f.seed_cache_for_tests(ROOT,CAT.as_bytes(),"text/html");f.seed_cache_for_tests(u,DETAIL.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"gin_library","access":"public","enabled":true,"catalog_url":ROOT})).unwrap();let rows=GinLibrary.discover(&s,&f,Some(1)).await.unwrap();assert_eq!(rows.len(),1);assert!(rows[0].extra["discovery_error"].is_string());let(title,body,links)=record(DETAIL,&Url::parse(u).unwrap()).unwrap();let h=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&links)).unwrap().as_bytes());let row=PlanRow{source_id:s.id.clone(),doc_key:"fixture".into(),url:u.into(),title:Some(title),rendition:Some("html".into()),version:None,extra:json!({"snapshot":h})};let d=GinLibrary.extract(&s,&f,&row).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("registry_record"));assert!(d.warnings.iter().any(|x|x.contains("not publication dates")));assert!(d.date_observations.is_empty());let fs=d.search_metadata["native_fields"].as_array().unwrap();for (label,value) in [("Expected Publication Date","1 March 2026"),("Date of Last Evidence Search","1 November 2023"),("Guideline Publication Status","Development"),("Countries of Application","United States"),("Languages","English")] {assert!(fs.iter().any(|f|f["label"]==label&&f["value"]==value&&f["source_url"]==u&&f["scope"]=="gin_registry_record"),"missing {label}");}assert!(d.search_metadata["record_html"].as_str().unwrap().contains("Expected Publication Date"));}
}

