#[cfg(all(test, feature = "guideline-fixtures"))]
mod alias_404_node_fallback {
    use super::*;
    const CAT: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/guidelines/gin_library/catalog-alias-404-excerpt.html"));
    const NODE: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/guidelines/gin_library/node-68276.html"));
    const ALIAS: &str = "https://guidelines.ebmportal.com/allergie-presumee-aux-penicillines-evaluation-des-risques-pour-un-usage-optimal-et-securitaire-des";
    #[test]
    fn listing_node_id_resolves_a_404_alias_only_with_matching_title() {
        let base = Url::parse(ROOT).unwrap();
        let (urls, _) = catalog(CAT, &base).unwrap();
        assert_eq!(urls, vec![ALIAS.to_string()]);
        let nids = catalog_nids(CAT, &base);
        let (node, listed) = node_fallback(ALIAS, &nids).unwrap();
        assert_eq!(node, "https://guidelines.ebmportal.com/node/68276");
        assert!(listed.starts_with("Allergie présumée aux pénicillines"));
        let nb = Url::parse(&node).unwrap();
        let note = accept_node(ALIAS, &node, &listed, NODE, &nb).unwrap();
        assert!(note.contains("HTTP 404") && note.contains("/node/68276"));
        assert!(accept_node(ALIAS, &node, "Another guideline", NODE, &nb).is_err());
        assert!(node_fallback("https://guidelines.ebmportal.com/unlisted", &nids).is_none());
    }
}
